//! The release index: every Grand Theft Auto game and every release, edition and version the
//! cited sources list (`data/release_index.json`, generated by `tools/gen_release_index.py` from
//! pinned redump / No-Intro DATs, Wikipedia revisions and titledb; see that script).
//!
//! Detection uses it to name console releases (serials, Dreamcast IP.BIN fields, ROM hashes) and
//! PC discs (redump track sizes and hashes). The Index and Documentation pages of the desktop app
//! show it. Releases no source lists are absent; the known holes are [`Index::gaps`].

use std::collections::BTreeMap;
use std::sync::OnceLock;

use serde::Deserialize;

use crate::{Game, Platform};

#[derive(Debug, Clone, Deserialize)]
pub struct Source {
    pub name: String,
    pub url: String,
    pub pin: String,
    pub license: String,
}

#[derive(Debug, Clone, Deserialize)]
pub struct FileHash {
    pub name: String,
    pub size: u64,
    pub sha1: String,
}

/// Dreamcast `IP.BIN` header fields of a disc, as redump shows them.
#[derive(Debug, Clone, Deserialize)]
pub struct IpBin {
    pub product: String,
    pub version: String,
    pub date: String,
    pub source: String,
}

#[derive(Debug, Clone, Deserialize)]
pub struct Update {
    pub version: u64,
    pub date: String,
}

#[derive(Debug, Clone, Deserialize)]
pub struct Release {
    /// A platform id of [`Index::platforms`] (`pc`, `ps1`, `dc`, `switch`, ...).
    pub platform: String,
    /// The DAT title, e.g. "Grand Theft Auto 2 (Europe) (En,Fr,De,Es,It) (Rev 1)".
    pub title: String,
    pub region: String,
    pub languages: String,
    /// "v1.03", "Rev 1", ... when the DAT names one.
    pub version: String,
    /// The other title tags: editions ("Rockstar Classics", "Sold Out Software"), disc numbers.
    pub tags: Vec<String>,
    pub serial: String,
    /// `disc`, `umd`, `rom` or `digital`.
    pub media: String,
    pub files: Vec<FileHash>,
    pub source: String,
    /// Game ids this release holds (several for a compilation).
    pub games: Vec<String>,
    #[serde(default)]
    pub ip_bin: Option<IpBin>,
    #[serde(default)]
    pub date: Option<String>,
    #[serde(default)]
    pub updates: Vec<Update>,
}

impl Release {
    /// The region and tags as one label, e.g. "Europe, En,Fr,De,It, Sold Out Software".
    pub fn label(&self) -> String {
        let mut parts = vec![self.region.clone()];
        parts.extend([self.languages.clone(), self.version.clone()].into_iter().filter(|s| !s.is_empty()));
        parts.extend(self.tags.iter().cloned());
        parts.join(", ")
    }
}

#[derive(Debug, Clone, Deserialize)]
pub struct PlatformDate {
    pub platform: String,
    /// The platform heading as the source wrote it.
    pub label: String,
    /// Region code as the source wrote it (NA, EU, PAL, WW, ...); empty when none is given.
    pub region: String,
    /// `YYYY-MM-DD`, `YYYY-MM` or `YYYY`.
    pub date: String,
    pub source: String,
}

#[derive(Debug, Clone, Deserialize)]
pub struct Build {
    pub platform: String,
    pub id: String,
    pub label: String,
    pub identify: String,
    pub source: String,
}

#[derive(Debug, Clone, Deserialize)]
pub struct IndexGame {
    pub id: String,
    pub title: String,
    /// The [`Game::cli_id`] when Eyefinder reads this game.
    pub eyefinder: Option<String>,
    pub developer: String,
    pub publisher: String,
    pub first_release: Option<String>,
    pub platform_dates: Vec<PlatformDate>,
    pub releases: Vec<Release>,
    pub builds: Vec<Build>,
    #[serde(default)]
    pub wikipedia: Option<String>,
}

impl IndexGame {
    pub fn game(&self) -> Option<Game> {
        self.eyefinder.as_deref().and_then(Game::from_cli_id)
    }
    /// Platform ids with a release or a release date, in first-release order.
    pub fn platforms(&self) -> Vec<String> {
        let mut v: Vec<(String, String)> = Vec::new();
        for d in &self.platform_dates {
            match v.iter_mut().find(|(p, _)| *p == d.platform) {
                Some(e) if d.date < e.1 => e.1 = d.date.clone(),
                Some(_) => {}
                None => v.push((d.platform.clone(), d.date.clone())),
            }
        }
        for r in &self.releases {
            if !v.iter().any(|(p, _)| *p == r.platform) {
                v.push((r.platform.clone(), "9999".into()));
            }
        }
        v.sort_by(|a, b| a.1.cmp(&b.1).then(a.0.cmp(&b.0)));
        v.into_iter().map(|(p, _)| p).collect()
    }
    /// The earliest date the sources give for `platform`.
    pub fn first_on(&self, platform: &str) -> Option<&str> {
        self.platform_dates.iter().filter(|d| d.platform == platform).map(|d| d.date.as_str()).min()
    }
}

#[derive(Debug, Clone, Deserialize)]
pub struct Gap {
    pub platforms: String,
    pub text: String,
}

#[derive(Debug, Deserialize)]
pub struct Index {
    pub generator: String,
    pub sources: BTreeMap<String, Source>,
    pub platforms: BTreeMap<String, String>,
    pub games: Vec<IndexGame>,
    pub gaps: Vec<Gap>,
}

static INDEX: OnceLock<Index> = OnceLock::new();

/// The embedded index.
pub fn index() -> &'static Index {
    INDEX.get_or_init(|| {
        serde_json::from_str(include_str!("../data/release_index.json")).expect("data/release_index.json is valid")
    })
}

/// The index platform id of an Eyefinder platform.
pub fn platform_id(p: Platform) -> &'static str {
    match p {
        Platform::Pc => "pc",
        Platform::Ps1 => "ps1",
        Platform::Ps2 => "ps2",
        Platform::Xbox => "xbox",
        Platform::Dreamcast => "dc",
        Platform::GameBoyColor => "gbc",
        Platform::GameBoyAdvance => "gba",
        Platform::Unknown => "",
    }
}

/// The Eyefinder platform of an index platform id; `None` for platforms Eyefinder does not read
/// (`android`, `ios`, `ps3`, ...).
pub fn platform_of(id: &str) -> Option<Platform> {
    Platform::ALL.iter().copied().find(|&p| platform_id(p) == id)
}

/// The serial a DAT lists, reduced to the boot file's serial: DATs add variant suffixes
/// (`SLUS-00106CE`, `SLES-00032/COLL.`, `SLES-000322` for redump's `#2`) and list several serials
/// separated by commas.
pub fn serials(dat: &str, platform: Platform) -> Vec<String> {
    dat.split(',')
        .filter_map(|s| {
            let s = s.trim();
            if platform == Platform::Ps1 || platform == Platform::Ps2 {
                let b = s.as_bytes();
                (b.len() >= 10 && b[..4].iter().all(u8::is_ascii_uppercase) && b[4] == b'-')
                    .then(|| s[..10].to_string())
                    .filter(|x| x[5..].bytes().all(|c| c.is_ascii_digit()))
            } else {
                (!s.is_empty()).then(|| s.to_string())
            }
        })
        .collect()
}

impl Index {
    pub fn game(&self, id: &str) -> Option<&IndexGame> {
        self.games.iter().find(|g| g.id == id)
    }
    pub fn of(&self, game: Game) -> Option<&IndexGame> {
        self.games.iter().find(|g| g.eyefinder.as_deref() == Some(game.cli_id()))
    }
    /// Every release, with the game entry it is listed under.
    pub fn releases(&self) -> impl Iterator<Item = (&IndexGame, &Release)> {
        self.games.iter().flat_map(|g| g.releases.iter().map(move |r| (g, r)))
    }
    pub fn platform_name<'a>(&'a self, id: &'a str) -> &'a str {
        self.platforms.get(id).map_or(id, |s| s.as_str())
    }
    /// Releases of `platform` whose DAT serial is `serial`.
    pub fn by_serial(&self, platform: Platform, serial: &str) -> Vec<(&IndexGame, &Release)> {
        let pid = platform_id(platform);
        self.releases()
            .filter(|(_, r)| {
                r.platform == pid && serials(&r.serial, platform).iter().any(|s| s.eq_ignore_ascii_case(serial))
            })
            .collect()
    }
    /// Dreamcast discs whose IP.BIN product number, version and date are these.
    pub fn by_ip_bin(&self, product: &str, version: &str, date: &str) -> Vec<(&IndexGame, &Release)> {
        self.releases()
            .filter(|(_, r)| {
                r.ip_bin.as_ref().is_some_and(|i| i.product == product && i.version == version && i.date == date)
            })
            .collect()
    }
    /// ROM dumps with this SHA-1 (lower-case hex).
    pub fn by_sha1(&self, sha1: &str) -> Vec<(&IndexGame, &Release)> {
        self.releases().filter(|(_, r)| r.files.iter().any(|f| f.sha1 == sha1)).collect()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_embedded_index_is_complete_and_cited() {
        let i = index();
        assert!(i.games.len() >= 17);
        for g in &i.games {
            for r in &g.releases {
                assert!(i.sources.contains_key(&r.source), "{} cites unknown source {}", r.title, r.source);
                assert!(i.platforms.contains_key(&r.platform), "{}: platform {}", r.title, r.platform);
                assert!(!r.games.is_empty() && r.games.iter().all(|id| i.game(id).is_some()), "{}", r.title);
                if let Some(ip) = &r.ip_bin {
                    assert!(i.sources.contains_key(&ip.source));
                }
            }
            for d in &g.platform_dates {
                assert!(i.sources.contains_key(&d.source));
            }
            for b in &g.builds {
                assert!(i.sources.contains_key(&b.source));
            }
            if let Some(id) = &g.eyefinder {
                assert!(Game::from_cli_id(id).is_some(), "{id}");
            }
        }
        // Every Eyefinder game has an entry.
        for g in Game::ALL {
            assert!(i.of(g).is_some(), "{g:?}");
        }
        assert!(!i.gaps.is_empty());
    }

    #[test]
    fn lookups() {
        let i = index();
        let ps1 = i.by_serial(Platform::Ps1, "SLES-01404");
        assert!(ps1.iter().all(|(g, _)| g.id == "gta2") && !ps1.is_empty());
        let dc = i.by_ip_bin("T40502D 93", "V1.003", "20000702");
        assert!(dc.iter().all(|(_, r)| r.title.starts_with("Grand Theft Auto 2 (Europe)")) && dc.len() == 2);
        assert_eq!(serials("SLUS-00106CE, SLES-00032/COLL.", Platform::Ps1), ["SLUS-00106", "SLES-00032"]);
        for p in Platform::ALL {
            assert_eq!(platform_of(platform_id(p)), Some(p));
        }
        for id in ["android", "ios", "mac", "ps3", ""] {
            assert_eq!(platform_of(id), None, "{id}");
        }
        // "Advance GTA" (Japan) is another game and is not in the index.
        assert!(i.releases().all(|(_, r)| !r.title.starts_with("Advance GTA")));
    }
}
